using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
namespace Downfield {
public static class ClubUpdateTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Club update: "+name);}}
 static void Call(object o,string method,params object[] args){o.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic,null,Array.ConvertAll(args,a=>a.GetType()),null).Invoke(o,args);}
 static Franchise Club(){return Franchise.Create(new Profile(),new Roster());}
 static Franchise PassingClub(bool elite){Franchise f=Club();foreach(ClubPlayer p in f.Players)if(p.Team==0&&(p.Role=="QB"||p.Role=="WR"||p.Role=="TE")){p.Hands=p.Power=p.Speed=p.OVR=elite?99:70;}return f;}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-club-update-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{Franchise f=Club();f.FinishGame(f.UserGame.Id,28,14);HashSet<int> teams=new HashSet<int>();foreach(SeasonProduction p in f.StatLeaders(0))teams.Add(p.Team);Check(teams.Count==12,"all twelve clubs produce competing award candidates");foreach(int category in new int[]{2,3,4}){List<SeasonProduction> leaders=f.StatLeaders(category);bool sorted=leaders.Count>0;for(int i=1;i<leaders.Count;i++)sorted&=category==2?leaders[i-1].PassYards>=leaders[i].PassYards:category==3?leaders[i-1].RushYards>=leaders[i].RushYards:leaders[i-1].RecYards>=leaders[i].RecYards;Check(sorted,"stat category sorts actual yards: "+category);}
  Franchise strong=PassingClub(true),weak=PassingClub(false);for(int i=0;i<40;i++){Fixture game=new Fixture{Id=100+i,Home=0,Away=1};Call(strong,"SimulatedBox",game,0,21);Call(weak,"SimulatedBox",game,0,21);}int qb=strong.Starter(0,0).Id;SeasonProduction a=strong.Production.Find(p=>p.PlayerId==qb),b=weak.Production.Find(p=>p.PlayerId==qb);Check(a.PassYards>b.PassYards*1.2&&a.Completions>b.Completions,"ratings meaningfully change simulated passing competition");int received=0,catches=0,td=0;foreach(SeasonProduction p in strong.Production)if(p.Role=="WR"||p.Role=="TE"){received+=p.RecYards;catches+=p.Catches;td+=p.RecTD;}Check(received==a.PassYards&&catches==a.Completions&&td==a.PassTD,"simulated receiving totals reconcile with quarterback totals");
  f=Club();f.Credits=1000;while(!f.Complete){if(f.UserGame==null)f.Advance();else f.FinishGame(f.UserGame.Id,35,7);}SeasonProduction mvp=f.StatLeaders(0)[0],offense=f.StatLeaders(1)[0];Check(f.Awards.Find(p=>p.Type=="MVP").PlayerId==mvp.PlayerId&&f.Awards.Find(p=>p.Type=="OPOTY").PlayerId==offense.PlayerId,"final trophies use same rankings as visible award races");SeasonAward award=f.Awards.Find(p=>p.Type=="MVP");Check(award.Number>0&&award.OVR>=70&&award.Role.Length>0,"award keeps winner profile for historical portraits");f.Save();Franchise loaded=Franchise.Load(new Profile(),new Roster());Check(loaded.Awards.Find(p=>p.Type=="MVP").PlayerId==award.PlayerId,"award profile snapshot survives save/load");
  Simulation s=LinePlayTests.TruckScene(1);Call(s,"TruckImpact",s.Players[1],true);Player victim=s.Players[1];Check(s.SpectacularHits==1&&victim.ImpactLevel==2&&victim.KnockTime>1,"power truck produces extended spectacular launch");float start=victim.Z;Call(s,"EndPlay",24f,"TACKLED",false);float deadSpot=s.Spot;for(int i=0;i<30;i++)s.Update(.02f,0,0);Check(victim.Z-start>4&&s.Spot==deadSpot,"large launch travels several yards without moving dead-ball spot");for(int i=0;i<40;i++)s.Update(.02f,0,0);Check(victim.KnockTime==0,"spectacular fall recovers without stuck player");s=LinePlayTests.TruckScene(4);Call(s,"ArcadeContact",s.Controlled,0f,-1f,15f,false);Check(s.Controlled.ImpactLevel==2&&s.SpectacularHits==1,"defense can launch ball carrier on heavy closing contact");
  Console.WriteLine("Club update: "+checks+" checks, "+failures+" failures");return failures;
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}}
}
}
